[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:HowTo ;
                    schema1:step [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:description "HCl and HF acid dissolution residue from pristine Tagish Lake pieces; deposited on lacey C TEM grid attached to Al-SEM stub; uncoated" ;
                            schema1:name "Sample preparation" ;
                            schema1:position 1 ;
                            ns1:coarseMillingConditionsDefault "no value available: ada:coarseMillingConditionsDefault" ;
                            ns1:finePolishingConditionsDefault "no value available: ada:finePolishingConditionsDefault" ;
                            ns1:liftOutMethod "missing" ;
                            ns1:protectiveCoatingDepositionDefault "no value available: ada:protectiveCoatingDepositionDefault" ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:description "no value available: schema:description" ;
                            schema1:name "Ion milling" ;
                            schema1:position 3 ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:name "Data processing" ;
                            schema1:position 2 ;
                            ns1:detectionLimitMethod "no value available: ada:detectionLimitMethod" ;
                            ns1:ebsdIndexingMethod "missing" ] ] ;
            sh:resultMessage "A HowTo methodology must have a schema:name" ;
            sh:resultPath schema1:name ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "A HowTo methodology must have a schema:name" ;
                    sh:minCount 1 ;
                    sh:path schema1:name ;
                    sh:severity sh:Violation ] ] .

